	(108, '2025-10-18 16:49:31.292161+00', 'Coversyl Plus Arginine Servier (Hộp 30 viên)', NULL, NULL, 'Cove123', NULL, NULL, NULL, 'Thuốc tim mạch huyết áp', '{Perindopril,Indapamid,"Tăng huyết áp","Cao huyết áp"}', 'Les Laboratoires Servier (France/Pháp)', NULL, NULL, 'Hộp 30 Viên', 'Coversyl Plus là sản phẩm của Les Laboratoires Servier (France/Pháp), chứa perindopril arginin và indapamid. Thuốc này dùng để điều trị tăng huyết áp và huyết áp cao.', NULL, NULL, NULL, 'Liều thường dùng là một viên nén một lần trong ngày, uống vào buổi sáng và trước bữa ăn.', 'Tăng huyết áp, huyết áp cao', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, '', 'Uống', NULL, NULL, 0, 0, NULL, NULL, false, 5.00),
	(104, '2025-09-19 04:01:38.391721+00', 'Amoxicilin 500mg TW1 (10 vỉ x 10 viên)', 150000, NULL, 'Amo500', 'goods', false, '', 'Thuốc kháng sinh', '{Amoxicillin,"kháng sinh",penicillin,"nhiễm khuẩn","viêm phế quản","viêm phổi","viêm tai giữa","nhiễm trùng đường tiết niệu","nhiễm trùng da"}', '', 'GIGAMED - DSKH', '', '', 'Amoxicilin 500mg TW1 là thuốc kháng sinh bán tổng hợp thuộc nhóm penicillin, hiệu quả trong điều trị nhiều loại nhiễm khuẩn đường hô hấp, tai mũi họng, tiết niệu và da.  Với hàm lượng 500mg/viên, thuốc giúp kiểm soát nhiễm khuẩn nhanh chóng và hiệu quả.  Luôn tuân thủ chỉ định của bác sĩ để đạt hiệu quả điều trị tối ưu và tránh tác dụng phụ.', '', '', '', '', '', false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, 'https://files2.nhathuocduochanoi.com.vn/image?f=auto&w=1024&url=content/0000/8/2024/11/20/4203-amoxicilin-500mg-tw1-2.jpg', NULL, NULL, NULL, 0, 0, NULL, NULL, false, 5.00),
	(100, '2025-09-18 03:48:11.900217+00', 'Augxicine 1g  (4 vỉ x 7 viên)', 300000, 35000, '271', 'goods', true, NULL, 'Thuốc kháng sinh', '{"[\"Amoxicillin\"","\"Clavulanic acid\"","\"Kháng sinh\"","\"Nhiễm khuẩn\"]"}', NULL, 'Trung Ương 1', NULL, '4 vỉ x 7 viên', 'Augxicine 1g được dùng để điều trị trong thời gian ngắn các trường hợp nhiễm khuẩn do vi khuẩn nhạy cảm. Ví dụ như nhiễm khuẩn đường hô hấp trên và dưới, nhiễm khuẩn đường tiết niệu - sinh dục, nhiễm khuẩn da và mô mềm, nhiễm khuẩn xương khớp, và nhiễm khuẩn nha khoa.', NULL, NULL, NULL, NULL, 'Viêm amidan, viêm xoang, viêm tai giữa, viêm phế quản cấp và mạn, viêm phổi - phế quản, viêm bàng quang, viêm niệu đạo, viêm bể thận, mụn nhọt, áp xe, nhiễm khuẩn vết thương, viêm tủy xương, áp xe ổ răng', false, 'Hộp', 'Vỉ', 10, NULL, 20000, 50000, 320000, true, 'https://vidipha.com.vn/img/vidipha/products/10%20Augixicine%201g-H_14%20_%20100.JPG', NULL, 2, NULL, 0, 0, NULL, NULL, false, 5.00),
	(99, '2025-09-18 03:45:57.799162+00', 'Miduc Saga Laboratories (Hộp 01 vỉ x 10 viên)', 100000, 150000, '1135', 'goods', true, '8902297008061', 'Thuốc Chống Nấm', '{"[\"Itraconazole\"","\"Kháng nấm\"","\"Nấm da\"","\"Nấm móng\"","\"Nấm Candida\"]"}', 'Saga Laboratories', 'Trung Ương 1', 'VN-17669-14', 'Hộp 01 vỉ x 10 viên', 'Miduc là thuốc kháng nấm chứa Itraconazole, được chỉ định điều trị các bệnh nấm như nấm da, nấm móng và nấm Candida âm đạo dai dẳng. Thuốc có tác dụng ức chế sinh tổng hợp ergosterol, gây rối loạn chức năng màng tế bào nấm. Uống thuốc sau bữa ăn để tăng hấp thu.', NULL, NULL, NULL, 'Tùy thuộc vào mức độ nhiễm nấm, liều đề nghị 1 viên 1 ngày trong 12 tuần hoặc 2 viên 1 ngày trong 1 tuần : Sau ăn', 'Nấm Candida âm đạo, nấm da, nấm móng, viêm giác mạc do nấm Candida', true, 'Hộp', 'Vỉ', 1, NULL, 10000, 50000, 110000, true, 'https://bizweb.dktcdn.net/thumb/grande/100/492/516/products/miduc-100mg-itraconazol-h10vna-india-imihv.jpg?v=1700792810940', NULL, 2, NULL, 0, 0, NULL, NULL, false, 5.00),
	(101, '2025-09-18 03:49:22.868793+00', 'Bibone Vitamin D3 400IU BMP (Hộp 1 lọ)', 100000, 150000, '1447', 'goods', true, '8938506192641', 'Thực phẩm chức năng', '{"[\"Vitamin D3\"","\"Omega 3\"","\"Vitamin K2\"","\"Còi xương\"","\"Loãng xương\"]"}', 'CÔNG TY CP THƯƠNG MẠI DƯỢC PHẨM BÌNH MINH', 'Vidipha', '8210/2021/DKSP', 'Hộp 1 lọ 20ml', 'Bibone Vitamin D3 400IU giúp tăng cường hấp thu canxi vào xương, giảm nguy cơ mắc bệnh còi xương ở trẻ em và phòng tránh loãng xương ở người lớn do tiêu xương, giảm tái tạo xương hoặc thiếu vitamin D. Sản phẩm bổ sung Vitamin D3, Omega 3, Vitamin K2, hỗ trợ phát triển hệ xương và răng.', 'Trẻ dưới 6 tháng tuổi: dùng theo chỉ định riêng của bác sĩ.', 'Trẻ từ 6-12 tháng tuổi: dùng 2 giọt x 2 lần/ngày.
