INSERT INTO "public"."posts" ("id", "created_at", "author_id", "title", "content", "post_type", "is_pinned", "attachments", "status") VALUES
	('9cdd8ca5-022f-437b-8c5c-d0d6a692043f', '2025-10-04 18:17:38.165857+00', '73807c61-e793-4543-bb0d-d01e88595228', 'Chi phí Thắp hương Bàn Thần Tài', '<p>Đối với chi phí thắp hương, có chi phí cố định như sau:</p><ul><li><p>Nhà thuốc 1: 200.000đ / tháng</p></li><li><p>Nhà thuốc 2: 200.000đ / tháng</p></li></ul><p>Tạm thời Đề xuất, chờ QL Duyệt</p><p></p>', 'suggestion', false, NULL, 'published'),
	('341e031f-e1e6-4868-a227-94730d9c830b', '2025-10-04 09:33:55.65168+00', '73807c61-e793-4543-bb0d-d01e88595228', 'Quy định sử dụng Hệ Thống ra Thông Báo Chung', '<p>Từ ngày 01/10/2025. Công ty Dược Nam Việt sẽ sử dụng Hệ thống chung "<a target="_blank" rel="noopener noreferrer nofollow" href="https://nam-viet-erp.vercel.app/">https://nam-viet-erp.vercel.app/</a>" để có thể ra các Thông Báo và Quy Định chung.</p><p>Đề nghị các thành viên truy câp Link trên để Đăng Ký Tài Khoản và Nhận các thông báo chung.</p><p>Quy định này sẽ có hiệu lực 01/10/2025 và đến khi có thông báo mới</p><p>Trân trọng!</p>', 'announcement', false, NULL, 'published'),
	('91dead90-842c-4ca6-9523-918a0bebb874', '2025-10-07 04:01:18.628203+00', 'd6cdda1b-7970-49df-a977-b5b34449bc57', 'Test Góp Ý', '<p><strong>Mô tả chi tiếtMô tả chi tiếtMô tả chi tiếtMô tả chi tiếtMô tả chi tiếtMô tả chi tiết</strong></p>', 'suggestion', false, NULL, 'pending_approval'),
	('15d81e96-5c10-4eeb-b3bb-81e1fa675cb3', '2025-10-07 04:04:09.456261+00', 'd6cdda1b-7970-49df-a977-b5b34449bc57', 'Test = Tiêu đề Đề xuất  và Góp Ý', '<ul><li><p><strong>Mô tả chi tiết</strong></p></li><li><p><strong>Mô tả chi tiếtMô tả chi tiết</strong></p></li><li><p><strong>Mô tả chi tiết</strong></p></li></ul><p></p>', 'suggestion', false, NULL, 'pending_approval');
